<?php
declare(strict_types=1);
session_start();
$root=dirname(__DIR__,3);
$cfg=require $root.'/config.php';
date_default_timezone_set($cfg['timezone']??'America/Argentina/Buenos_Aires');
$db=new PDO('mysql:host='.$cfg['db_host'].';dbname='.$cfg['db_name'].';charset=utf8mb4',$cfg['db_user'],$cfg['db_pass'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);
if(empty($_SESSION['user'])){header('Location:index.php');exit;}
$_SESSION['csrf']??=bin2hex(random_bytes(24));
function e($v):string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function go(string $u):never{header('Location:'.$u);exit;}
function csrf():void{if(!hash_equals($_SESSION['csrf']??'',$_POST['csrf']??'')){http_response_code(419);exit('Solicitud vencida.');}}
function admin():bool{return ($_SESSION['user']['role']??'')==='admin';}
function usd($n):string{return 'US$ '.number_format((float)$n,2,',','.');}
function brandFromCategory(string $cat):string{$x=mb_strtolower($cat);if(str_contains($x,'control4')||str_contains($x,'c4'))return 'Control4';if(str_contains($x,'shelly'))return 'Shelly';if(str_contains($x,'lifesmart')||str_contains($x,'domot'))return 'LifeSmart';return 'Otro';}
function replaceCharge(PDO $db,int $projectId,int $newChargeId,array $types):void{$m=implode(',',array_fill(0,count($types),'?'));$s=$db->prepare("SELECT id FROM charges WHERE project_id=? AND active=1 AND id<>? AND type IN ($m)");$s->execute(array_merge([$projectId,$newChargeId],$types));foreach($s as $old){$als=$db->prepare('SELECT payment_id,amount FROM allocations WHERE charge_id=?');$als->execute([$old['id']]);foreach($als as $al)$db->prepare('INSERT INTO allocations(payment_id,charge_id,amount) VALUES(?,?,?) ON DUPLICATE KEY UPDATE amount=amount+VALUES(amount)')->execute([$al['payment_id'],$newChargeId,$al['amount']]);$db->prepare('DELETE FROM allocations WHERE charge_id=?')->execute([$old['id']]);$db->prepare('UPDATE charges SET active=0 WHERE id=?')->execute([$old['id']]);}}

$a=$_GET['a']??'new_quote';

if($a==='save_quote'){
 if(!admin()){http_response_code(403);exit('No autorizado.');}
 csrf();
 try{
  $pid=(int)($_POST['project_id']??0);$clientId=(int)($_POST['client_id']??0);$listId=(int)($_POST['price_list_id']??0);
  $s=$db->prepare('SELECT p.*,c.id client_id FROM projects p JOIN clients c ON c.id=p.client_id WHERE p.id=? AND c.id=?');$s->execute([$pid,$clientId]);$project=$s->fetch();if(!$project)throw new Exception('Seleccioná un proyecto válido.');
  $families=array_values(array_intersect(['lifesmart','control4','shelly'],$_POST['quote_families']??[]));if(!$families)throw new Exception('Seleccioná al menos una familia.');$template=$_POST['quote_template_family']??'';if(!in_array($template,$families,true))$template=$families[0];
  $s=$db->prepare('SELECT id,name,markup_percentage FROM price_lists WHERE id=? AND active=1');$s->execute([$listId]);$list=$s->fetch();if(!$list)throw new Exception('Seleccioná una lista de precios.');$markup=(float)$list['markup_percentage'];
  $prodQ=$db->prepare("SELECT p.id,p.sku,p.description,p.unit,p.cost_usd,COALESCE(pc.name,'Otros') category FROM products p LEFT JOIN product_categories pc ON pc.id=p.category_id WHERE p.id=? AND p.active=1");
  $items=[];$materials=0;$sort=0;
  foreach($_POST['items']??[] as $r){$productId=(int)($r['product_id']??0);$qty=(float)($r['quantity']??0);if(!$productId||$qty<=0)continue;$prodQ->execute([$productId]);$p=$prodQ->fetch();if(!$p)continue;$unit=round((float)$p['cost_usd']*(1+$markup/100),2);$sub=round($qty*$unit,2);$materials+=$sub;$brand=brandFromCategory($p['category']);$items[]=[$productId,$p['category'],$brand,$p['sku'],$p['description'],$p['unit'],$qty,$unit,$listId,$sub,$sort++];}
  if(!$items)throw new Exception('Agregá al menos un producto.');
  $labor=max(0,(float)($_POST['labor_amount']??0));$matMode=$_POST['materials_tax_mode']??'sin_iva';$matVat=(float)($_POST['materials_vat_rate']??21);$labMode=$_POST['labor_tax_mode']??'sin_iva';$labVat=(float)($_POST['labor_vat_rate']??21);$factor=static fn(string $m,float $v):float=>$m==='mas_iva'?1+$v/100:1;$matTotal=round($materials*$factor($matMode,$matVat),2);$labTotal=round($labor*$factor($labMode,$labVat),2);$total=$matTotal+$labTotal;$version=max(1,(int)($_POST['version_no']??1));$date=$_POST['quote_date']??date('Y-m-d');$status=$_POST['status']??'borrador';$category=$_POST['quote_category']??'general';$notes=trim((string)($_POST['notes']??''));
  $db->beginTransaction();
  $db->prepare('INSERT INTO quotes(project_id,version_no,quote_category,currency,quote_date,quote_families,quote_template_family,price_list_id,materials_amount,labor_amount,subtotal,tax_mode,vat_rate,materials_tax_mode,materials_vat_rate,labor_tax_mode,labor_vat_rate,total,status,notes) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)')->execute([$pid,$version,$category,'USD',$date,implode(',',$families),$template,$listId,$materials,$labor,$materials+$labor,'sin_iva',21,$matMode,$matVat,$labMode,$labVat,$total,$status,$notes]);$qid=(int)$db->lastInsertId();
  $ins=$db->prepare('INSERT INTO quote_items(quote_id,product_id,category,brand,sku,description,unit,quantity,unit_price,price_list_id,subtotal,sort_order) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)');foreach($items as $r)$ins->execute(array_merge([$qid],$r));
  if($status==='aprobado_inicial'){$pct=(float)$project['engineering_pct'];$amt=round($total*$pct/100,2);$db->prepare("INSERT INTO charges(project_id,quote_id,charge_date,type,currency,description,amount) VALUES(?,?,?,'ingenieria','USD',?,?)")->execute([$pid,$qid,$date,'Adelanto de ingeniería '.$pct.'% · v'.$version,$amt]);$eng=(int)$db->lastInsertId();replaceCharge($db,$pid,$eng,['ingenieria']);$db->prepare("UPDATE projects SET status='aprobado' WHERE id=?")->execute([$pid]);}
  if($status==='final'){$db->prepare("INSERT INTO charges(project_id,quote_id,charge_date,type,currency,description,amount) VALUES(?,?,?,'materiales','USD',?,?)")->execute([$pid,$qid,$date,'Materiales · presupuesto final v'.$version,$matTotal]);$mat=(int)$db->lastInsertId();replaceCharge($db,$pid,$mat,['materiales']);if($labTotal>0){$db->prepare("INSERT INTO charges(project_id,quote_id,charge_date,type,currency,description,amount) VALUES(?,?,?,'mano_obra','USD',?,?)")->execute([$pid,$qid,$date,'Mano de obra · presupuesto final v'.$version,$labTotal]);$lab=(int)$db->lastInsertId();replaceCharge($db,$pid,$lab,['ingenieria','mano_obra']);}$db->prepare("UPDATE projects SET status='en_obra' WHERE id=?")->execute([$pid]);}
  $db->commit();$_SESSION['msg']='Presupuesto creado.';go('index.php?a=quote_view&id='.$qid);
 }catch(Throwable $ex){if($db->inTransaction())$db->rollBack();$_SESSION['msg']='No se pudo guardar: '.$ex->getMessage();go('index.php?a=new_quote');}
}

if(in_array($a,['quote_view','quote_print'],true)){
 $id=(int)($_GET['id']??0);$s=$db->prepare("SELECT q.*,p.project_number,p.name project_name,c.business_name,pl.name price_list_name,pl.markup_percentage FROM quotes q JOIN projects p ON p.id=q.project_id JOIN clients c ON c.id=p.client_id LEFT JOIN price_lists pl ON pl.id=q.price_list_id WHERE q.id=?");$s->execute([$id]);$q=$s->fetch();if(!$q)exit('Presupuesto inexistente.');$s=$db->prepare('SELECT * FROM quote_items WHERE quote_id=? ORDER BY sort_order,id');$s->execute([$id]);$items=$s->fetchAll();$print=$a==='quote_print';?>
<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Presupuesto <?=e($q['project_number'])?></title><style>*{box-sizing:border-box}body{margin:0;background:#eef1f4;color:#252b32;font:14px/1.45 Arial}.sheet{width:210mm;min-height:297mm;margin:18px auto;background:#fff;padding:18mm}.top{display:flex;justify-content:space-between;border-bottom:4px solid #ff6702;padding-bottom:14px}.brand{font-size:28px;font-weight:800}.meta{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin:24px 0}.box{border:1px solid #ddd;border-radius:8px;padding:12px}table{width:100%;border-collapse:collapse}th,td{padding:9px 7px;border-bottom:1px solid #ddd}th{text-align:left;background:#f5f6f7;font-size:11px;text-transform:uppercase}.right{text-align:right}.actions{width:210mm;margin:0 auto 18px;display:flex;gap:10px}.btn{padding:10px 14px;background:#ff6702;color:#fff;text-decoration:none;border-radius:7px;font-weight:700}.total{margin:22px 0 0 auto;width:330px}.total div{display:flex;justify-content:space-between;padding:6px 0}.grand{border-top:2px solid #252b32;font-size:20px;font-weight:800}@media print{body{background:#fff}.actions{display:none}.sheet{margin:0}}@media(max-width:900px){.sheet,.actions{width:auto}.sheet{padding:22px}}</style></head><body><?php if(!$print):?><div class="actions"><a class="btn" href="?a=quotes">← Presupuestos</a><a class="btn" href="?a=quote_print&id=<?=$id?>" target="_blank">Vista para PDF</a></div><?php endif;?><section class="sheet"><div class="top"><div><div class="brand">● Punto Domótica</div><div>Casas inteligentes</div></div><div class="right"><b>PRESUPUESTO</b><br><?=e(date('d/m/Y',strtotime($q['quote_date'])))?></div></div><div class="meta"><div class="box"><b>Cliente</b><br><?=e($q['business_name'])?></div><div class="box"><b>Proyecto</b><br><?=e($q['project_number'].' · '.$q['project_name'])?><br>Versión <?=e($q['version_no'])?> · USD<?php if($q['price_list_name']):?><br><?=e($q['price_list_name'])?> (+<?=e($q['markup_percentage'])?>%)<?php endif;?></div></div><h2>Equipamiento</h2><table><tr><th>SKU</th><th>Descripción</th><th>Marca</th><th>Cant.</th><th class="right">Unitario</th><th class="right">Subtotal</th></tr><?php foreach($items as $it):?><tr><td><b><?=e($it['sku']?:'—')?></b></td><td><?=e($it['description'])?><br><small><?=e($it['category'])?></small></td><td><?=e($it['brand'])?></td><td><?=e(number_format((float)$it['quantity'],2,',','.'))?></td><td class="right"><?=usd($it['unit_price'])?></td><td class="right"><?=usd($it['subtotal'])?></td></tr><?php endforeach;?></table><div class="total"><div><span>Materiales</span><b><?=usd($q['materials_amount'])?></b></div><?php if((float)$q['labor_amount']>0):?><div><span>Mano de obra</span><b><?=usd($q['labor_amount'])?></b></div><?php endif;?><div class="grand"><span>Total</span><span><?=usd($q['total'])?></span></div></div></section><?php if($print):?><script>window.addEventListener('load',()=>setTimeout(()=>window.print(),200));</script><?php endif;?></body></html><?php exit;
}

$clients=$db->query("SELECT id,business_name FROM clients WHERE active=1 ORDER BY business_name")->fetchAll();
$projects=$db->query("SELECT id,client_id,project_number,name FROM projects ORDER BY id DESC")->fetchAll();
$lists=$db->query("SELECT id,name,markup_percentage FROM price_lists WHERE active=1 ORDER BY id")->fetchAll();
$products=$db->query("SELECT p.id,p.sku,p.description,p.unit,p.cost_usd,COALESCE(pc.name,'Otros') category FROM products p LEFT JOIN product_categories pc ON pc.id=p.category_id WHERE p.active=1 ORDER BY pc.name,p.description")->fetchAll();
$maxv=$db->query('SELECT project_id,MAX(version_no) maxv FROM quotes GROUP BY project_id')->fetchAll();$versions=[];foreach($maxv as $v)$versions[(int)$v['project_id']]=(int)$v['maxv']+1;
$preProject=(int)($_GET['project_id']??0);$preClient=0;foreach($projects as $p)if((int)$p['id']===$preProject)$preClient=(int)$p['client_id'];
$msg=$_SESSION['msg']??null;unset($_SESSION['msg']);
$productJson=[];foreach($products as $p)$productJson[(int)$p['id']]=['id'=>(int)$p['id'],'sku'=>$p['sku'],'description'=>$p['description'],'unit'=>$p['unit'],'cost'=>(float)$p['cost_usd'],'category'=>$p['category'],'brand'=>brandFromCategory($p['category'])];
$listJson=[];foreach($lists as $l)$listJson[(int)$l['id']]=['id'=>(int)$l['id'],'markup'=>(float)$l['markup_percentage']];
?>
<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Nuevo presupuesto · Punto ERP</title><style>
:root{--o:#ff6702;--dark:#171b20;--ink:#27303b;--muted:#6e7781;--line:#e1e5e9;--bg:#f4f6f8;--sidebar:270px}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.45 system-ui}.sidebar{position:fixed;inset:0 auto 0 0;width:var(--sidebar);padding:28px 18px;background:var(--dark);color:#fff}.brand{font-size:22px;font-weight:800}.nav{display:flex;flex-direction:column;gap:5px;padding:24px 0}.nav a{padding:11px 13px;border-radius:9px;color:#d8dde3;text-decoration:none;font-weight:600}.nav a.active{background:var(--o);color:#fff}.main{margin-left:var(--sidebar);padding:32px 4%}.card{background:#fff;border:1px solid var(--line);border-radius:14px;padding:22px;margin-bottom:18px}.grid{display:grid;grid-template-columns:repeat(12,1fr);gap:16px}.c3{grid-column:span 3}.c4{grid-column:span 4}.c6{grid-column:span 6}.c8{grid-column:span 8}.c12{grid-column:span 12}label{display:block;font-weight:650;margin-bottom:6px}input,select,textarea{width:100%;padding:10px 11px;border:1px solid #cbd1d7;border-radius:8px;font:inherit;background:#fff}input[type=checkbox]{width:auto}.btn{border:0;border-radius:8px;padding:10px 15px;background:var(--o);color:#fff;text-decoration:none;font-weight:700;cursor:pointer}.btn.light{background:#edf0f3;color:var(--ink)}.muted{color:var(--muted)}.flash{padding:12px 16px;background:#fff0e5;border:1px solid #ffd2b1;border-radius:9px;margin-bottom:18px}table{width:100%;border-collapse:collapse}th,td{padding:9px;border-bottom:1px solid var(--line)}th{text-align:left;font-size:12px;color:var(--muted);text-transform:uppercase}.right{text-align:right}.actions{display:flex;gap:9px;align-items:center;flex-wrap:wrap}.family{display:flex;gap:20px;flex-wrap:wrap}.family label{font-weight:500}.remove{background:#edf0f3;color:#a22;padding:7px 10px}.totals{max-width:380px;margin-left:auto}.totals div{display:flex;justify-content:space-between;padding:7px 0}.grand{font-size:20px;font-weight:800;border-top:2px solid #333}@media(max-width:900px){.sidebar{display:none}.main{margin-left:0;padding:22px}.c3,.c4,.c6,.c8{grid-column:span 12}}
</style></head><body><aside class="sidebar"><div class="brand">● Punto ERP</div><div class="nav"><a href="index.php">Panel general</a><a href="?a=products">Productos</a><a href="?a=projects">Proyectos</a><a class="active" href="?a=quotes">Presupuestos</a></div></aside><main class="main"><?php if($msg):?><div class="flash"><?=e($msg)?></div><?php endif;?>
<div class="actions"><div style="flex:1"><span class="muted">Constructor</span><h1>Nuevo presupuesto</h1><p class="muted">Todos los precios se calculan en USD desde el costo y el porcentaje de la lista elegida.</p></div><a class="btn light" href="?a=quotes">Volver</a></div>
<form method="post" action="?a=save_quote"><input type="hidden" name="csrf" value="<?=e($_SESSION['csrf'])?>">
<div class="card grid"><p class="c4"><label>Cliente</label><select id="client" name="client_id" required><option value="">Seleccionar</option><?php foreach($clients as $c):?><option value="<?=$c['id']?>" <?=$preClient===(int)$c['id']?'selected':''?>><?=e($c['business_name'])?></option><?php endforeach;?></select></p><p class="c4"><label>Proyecto</label><select id="project" name="project_id" required><option value="">Seleccionar</option><?php foreach($projects as $p):?><option data-client="<?=$p['client_id']?>" value="<?=$p['id']?>" <?=$preProject===(int)$p['id']?'selected':''?>><?=e($p['project_number'].' · '.$p['name'])?></option><?php endforeach;?></select></p><p class="c4"><label>Versión</label><input id="version" type="number" min="1" name="version_no" value="1"></p><p class="c4"><label>Fecha</label><input type="date" name="quote_date" value="<?=date('Y-m-d')?>"></p><p class="c4"><label>Rubro</label><select name="quote_category"><option value="domotica">Domótica</option><option value="redes">Redes</option><option value="camaras">Cámaras</option><option value="alarma">Alarma</option><option value="audio">Audio</option><option value="general">General</option></select></p><p class="c4"><label>Lista de precios</label><select id="priceList" name="price_list_id" required><?php foreach($lists as $l):?><option value="<?=$l['id']?>"><?=e($l['name'])?> (+<?=e($l['markup_percentage'])?>%)</option><?php endforeach;?></select></p>
<div class="c6"><label>Familias incluidas</label><div class="family"><label><input type="checkbox" name="quote_families[]" value="lifesmart" checked> LifeSmart</label><label><input type="checkbox" name="quote_families[]" value="control4"> Control4</label><label><input type="checkbox" name="quote_families[]" value="shelly"> Shelly</label></div></div><p class="c6"><label>Plantilla principal</label><select name="quote_template_family"><option value="lifesmart">LifeSmart</option><option value="control4">Control4</option><option value="shelly">Shelly</option></select></p></div>
<div class="card"><div class="actions"><div style="flex:1"><h2>Equipamiento</h2><p class="muted">El precio unitario se completa automáticamente.</p></div><button class="btn" type="button" onclick="addRow()">+ Agregar producto</button></div><div style="overflow:auto"><table><thead><tr><th>Producto</th><th>SKU</th><th>Marca</th><th style="width:100px">Cant.</th><th class="right">Precio USD</th><th class="right">Subtotal</th><th></th></tr></thead><tbody id="items"></tbody></table></div><div class="totals"><div><span>Materiales</span><b id="materials">US$ 0,00</b></div></div></div>
<div class="card grid"><p class="c4"><label>Mano de obra USD</label><input id="labor" type="number" min="0" step=".01" name="labor_amount" value="0"></p><p class="c4"><label>IVA materiales</label><select name="materials_tax_mode"><option value="sin_iva">Sin IVA</option><option value="mas_iva">+ IVA</option><option value="iva_incluido">IVA incluido</option></select></p><p class="c4"><label>% IVA materiales</label><input type="number" step=".01" name="materials_vat_rate" value="21"></p><p class="c4"><label>IVA mano de obra</label><select name="labor_tax_mode"><option value="sin_iva">Sin IVA</option><option value="mas_iva">+ IVA</option><option value="iva_incluido">IVA incluido</option></select></p><p class="c4"><label>% IVA mano de obra</label><input type="number" step=".01" name="labor_vat_rate" value="21"></p><p class="c4"><label>Estado</label><select name="status"><option value="borrador">Borrador</option><option value="aprobado_inicial">Aprobado inicial</option><option value="final">Final</option></select></p><p class="c12"><label>Notas</label><textarea name="notes"></textarea></p></div><button class="btn">Guardar presupuesto</button></form>
<script>
const products=<?=json_encode($productJson,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)?>, lists=<?=json_encode($listJson)?>, versions=<?=json_encode($versions)?>;
let row=0;
const money=n=>'US$ '+Number(n||0).toLocaleString('es-AR',{minimumFractionDigits:2,maximumFractionDigits:2});
function filterProjects(){const c=document.getElementById('client').value,p=document.getElementById('project');[...p.options].forEach((o,i)=>{if(i===0)return;o.hidden=o.dataset.client!==c});if(p.selectedOptions[0]&&p.selectedOptions[0].hidden)p.value='';updateVersion()}
function updateVersion(){const id=document.getElementById('project').value;document.getElementById('version').value=versions[id]||1}
function productPrice(id){const p=products[id],l=lists[document.getElementById('priceList').value];return p&&l?Math.round((p.cost*(1+l.markup/100))*100)/100:0}
function options(){return '<option value="">Seleccionar producto</option>'+Object.values(products).map(p=>`<option value="${p.id}">${esc(p.sku)} · ${esc(p.description)}</option>`).join('')}
function esc(s){return String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]))}
function addRow(){const i=row++,tr=document.createElement('tr');tr.innerHTML=`<td><select name="items[${i}][product_id]" onchange="syncRow(this)" required>${options()}</select></td><td class="sku">—</td><td class="brand">—</td><td><input class="qty" type="number" min=".01" step=".01" name="items[${i}][quantity]" value="1" oninput="calc()"></td><td class="right price">—</td><td class="right sub">—</td><td><button class="btn remove" type="button" onclick="this.closest('tr').remove();calc()">×</button></td>`;document.getElementById('items').appendChild(tr)}
function syncRow(sel){const tr=sel.closest('tr'),p=products[sel.value];tr.dataset.product=sel.value;if(!p){tr.querySelector('.sku').textContent='—';tr.querySelector('.brand').textContent='—'}else{tr.querySelector('.sku').textContent=p.sku;tr.querySelector('.brand').textContent=p.brand}calc()}
function calc(){let total=0;document.querySelectorAll('#items tr').forEach(tr=>{const id=tr.dataset.product,price=productPrice(id),qty=Number(tr.querySelector('.qty').value||0),sub=price*qty;tr.querySelector('.price').textContent=id?money(price):'—';tr.querySelector('.sub').textContent=id?money(sub):'—';total+=sub});document.getElementById('materials').textContent=money(total)}
document.getElementById('client').addEventListener('change',filterProjects);document.getElementById('project').addEventListener('change',updateVersion);document.getElementById('priceList').addEventListener('change',calc);filterProjects();if(<?=count($products)?>)addRow();
</script></main></body></html>
